SELECT pu_location_id AS location_id, city, COUNT(DISTINCT order_id) AS num_orders, COUNT(DISTINCT trip_id) AS num_trips, SUM(total_amount) AS total_order_amount, SUM(fare_amount) AS total_trip_amount FROM (SELECT pu_location_id, NULL AS city, NULL AS order_id, trip_id, fare_amount, NULL AS total_amount FROM stg_nyc_taxi_trips UNION ALL SELECT NULL AS pu_location_id, city, order_id, NULL AS trip_id, NULL AS fare_amount, total_amount FROM stg_ecommerce_orders) AS combined GROUP BY pu_location_id, city LIMIT 100